import{homeEvent}from './home-event.js';
import{createReminders}from './reminders.js';
import{initPortraitMode}from './orientation.js';
import{registerAppWorker,checkAppUpdate}from './pwa-updates.js';
import{hijriForDay}from './hijri.js';
import{createBackup,validateBackup,restoreBackup}from './backup.js';
import{settings,updateSettings,history,markPrayer,storageAvailable,storageWarnings}from './storage.js';
import{usesAlHakk,prayers,methods,dateKey,addDays,cachedDays,loadMonth,timingsFor,asrInfo,nextPrayer,formatTime,countdown,bearing}from './prayers.js';
import{loadWeather,cachedWeather,weatherName,weatherFrame,weatherKey,atmosphere,startScenePreview,startWeatherPreview}from './weather.js';
import{esc,toast,modal,closeModal,title}from './ui.js';
import{PrayerDisplay}from './prayer-display.js';
import{tahajjudFor,personalTime}from './tahajjud.js';
import{showKnowledge}from './knowledge.js';
import{showQuran,stopQuran}from './quran.js';
import{bindQiblaSwipe}from './home-swipe.js';
import{mountQibla,prepareQiblaAccess,initQiblaAccess}from './qibla.js';
import{showLearning,stopLearning}from './learning.js';
import{showAdhkar,stopAdhkar,adhkarHomeCard,selectAdhkar}from './adhkar.js';
let days=cachedDays(),weather=cachedWeather(),error='',loading=false,currentDay=dateKey(),currentRoute='',qiblaHandle=null,refreshId=0;
const routes=[['home','Главная','⌂'],['knowledge','Знания','▧'],['quran','Коран','▤'],['adhkar','Азкары','◌'],['more','Ещё','⋯']];
let prayerDisplay='timetable',learningEntry=null,quranRenderedHash=null;
const app=document.getElementById('app');
const topHeader=document.querySelector('.workspace>header'),locationControl=document.getElementById('location-button'),settingsControl=document.getElementById('settings-button');
const reminders=createReminders({getSettings:()=>settings,updateSettings,getContext:()=>({today:dateKey(),days,cityKey:JSON.stringify([settings.city?.latitude,settings.city?.longitude,settings.city?.timezone,settings.method,settings.school,settings.highLatitude,settings.offsets,settings.mosque,settings.mosqueTimes]),timingsFor:day=>timingsFor(day,days)}),toast});
initPortraitMode();
initQiblaAccess({onGranted:()=>{if(qiblaHandle?.controller&&!qiblaHandle.controller.enabled)qiblaHandle.controller.enable();}});
function nav(){const iconNames={home:'house',knowledge:'journal-bookmark',quran:'book',adhkar:'circle',more:'person'};const activeRoute=currentRoute==='learning'?'knowledge':currentRoute;for(const id of ['desktop-nav','mobile-nav'])document.getElementById(id).innerHTML=routes.map(([key,name,icon])=>'<a class="nav-item '+(activeRoute===key?'active':'')+'" '+(activeRoute===key?'aria-current="page"':'')+' href="#'+key+'"><span class="nav-symbol" aria-hidden="true">'+('<img src="./assets/'+iconNames[key]+'.svg" alt="">')+'</span>'+name+'</a>').join('');document.getElementById('location-button').textContent=settings.city?settings.city.name:'Укажите город'}
function dateHeader(){const zone=settings.city?.timezone;const today=new Intl.DateTimeFormat('ru-RU',{timeZone:zone,day:'numeric',month:'long',year:'numeric'}).format(new Date());const h=days[currentDay]?.hijri;return '<div class="date"><strong>'+ (h?esc(h.day+' '+['Мухаррам','Сафар','Раби аль-авваль','Раби аль-ахир','Джумада аль-уля','Джумада аль-ахира','Раджаб','Шаабан','Рамадан','Шавваль','Зуль-када','Зуль-хиджа'][h.month.number-1]+' '+h.year):'')+'</strong><span>'+today+'</span></div>'}
function schedule(){const times=timingsFor(currentDay,days),next=nextPrayer(Date.now(),currentDay,days);return '<div class="panel-head"><h2>Намазы сегодня</h2><a class="text-button" href="#calendar">Календарь</a></div>'+prayers.map(([key,name])=>'<div class="prayer-row '+(next?.key===key?'next':'')+'"><span class="name">'+name+'</span><button class="schedule-time" data-time-toggle aria-label="Крупный отсчёт до ближайшего намаза"><time>'+ (times?formatTime(times[key]):'—')+'</time></button><button class="mark '+(history[currentDay]?.[key]?'done':'')+'" data-mark="'+key+'" aria-label="'+(history[currentDay]?.[key]?'Изменить отметку: ':'Отметить молитву: ')+name+'">'+(history[currentDay]?.[key]?'✓':'○')+'</button></div>').join('')+'<div class="sunrise"><span>☼ Восход · не является намазом</span><time>'+(times?formatTime(times.Sunrise):'—')+'</time></div>'}
function dayPanel(){const count=prayers.filter(([k])=>history[currentDay]?.[k]).length;return '<section class="panel day"><div class="panel-head"><h2>Мой день</h2><span class="muted">'+count+' из 5 отмечены</span></div><div class="day-dots">'+prayers.map(([k,n])=>'<div class="day-dot"><button class="day-mark '+(history[currentDay]?.[k]?'done':'')+'" data-day-mark="'+k+'" aria-pressed="'+Boolean(history[currentDay]?.[k])+'" aria-label="'+n+': '+(history[currentDay]?.[k]?'совершён':'не отмечен')+'">'+(history[currentDay]?.[k]?'✓':'○')+'</button>'+n+'</div>').join('')+'</div><div class="progress"><span style="width:'+count*20+'%"></span></div><p class="muted" style="margin:17px 0 0">Ваши отметки видны только вам.</p></section>'}
function hero(){const next=nextPrayer(Date.now(),currentDay,days);return '<section class="hero"><button class="time-toggle" data-time-toggle aria-expanded="'+(prayerDisplay==='focus')+'" aria-label="'+(prayerDisplay==='focus'?'Показать расписание на день':'Показать крупный отсчёт до ближайшего намаза')+'"><span class="eyebrow">СЛЕДУЮЩИЙ НАМАЗ</span><span class="next-prayer-name" id="next-name">'+(next?next.name:settings.city?'Расписание':'Ваш город')+'</span><span class="prayer-time" id="next-time">'+(next?formatTime(next.time):'—')+'</span><span class="countdown" id="countdown">'+(next?countdown(next.time-Date.now()):'— : — : —')+'</span><span class="hero-note" id="next-note">'+(next?'':loading?'Загружаем проверенные времена':settings.city?'Данные пока недоступны':'Выберите город для расчёта')+'</span><span class="toggle-hint">'+(prayerDisplay==='focus'?'Нажмите, чтобы открыть расписание на день':'Нажмите на время, чтобы открыть отсчёт')+'</span></button><div class="hero-bottom"><button class="weather-button" id="weather-status">'+weatherLabel()+'</button><a href="#qibla" class="chip">◎ Кибла</a></div></section>'}
function weatherLabel(){if(!settings.weather)return'Погода выключена';if(weatherFrame(weather,Date.now()).fresh)return Math.round(weather.temperature_2m)+'° · '+weatherName(weather.weather_code);return weatherBusy?'Обновляем погоду…':weather?'Погода устарела':'Свежая погода пока недоступна'}
function tahajjudEntry(now=Date.now(),chosenTime=settings.tahajjudTime){const value=tahajjudFor(now,{previous:timingsFor(addDays(currentDay,-1),days),today:timingsFor(currentDay,days),next:timingsFor(addDays(currentDay,1),days)},chosenTime);return value?{...value,text:value.kind==='manual'?value.text:formatTime(value.time)}:null}
async function ensureTahajjudDays(){const id=refreshId,day=currentDay,previousDay=addDays(day,-1);if(!settings.showTahajjud||!settings.city||days[previousDay])return;try{const fetched=await loadMonth(previousDay);if(id===refreshId&&day===currentDay)days={...days,...fetched}}catch{/* An absent adjacent date stays unavailable. */}}
function centralSurface(){const now=Date.now(),times=timingsFor(currentDay,days),next=homeEvent(now,nextPrayer(now,currentDay,days),times?.Sunrise,currentDay);return PrayerDisplay({mode:prayerDisplay,next,times,loading,hasCity:!!settings.city,asr:asrInfo(currentDay,days),nextAsr:next?asrInfo(next.day,days):null,tahajjud:settings.showTahajjud?{shown:true,...tahajjudEntry(now)}:null})}
function home(){app.innerHTML='<div class="app-home-shell"><div class="home-prayer-center"><div class="app-home-top"><div class="app-home-brand">SALAH</div><div id="home-location-controls" class="home-location-controls"></div></div>'+centralSurface()+'</div></div>';document.getElementById('home-location-controls').append(locationControl);bindMarks();bindQiblaSwipe(app.querySelector('.central-prayer.timetable'),()=>{prepareQiblaAccess();location.hash='qibla'})}
function dataNote(){const friday=new Intl.DateTimeFormat('en-US',{timeZone:settings.city?.timezone,weekday:'long'}).format(new Date())==='Friday';const juma=friday?'<section class="panel friday-card"><span class="eyebrow">ПЯТНИЦА</span><h3 style="margin-top:14px">Джума</h3><p class="muted">'+(settings.juma?'В вашей мечети: '+esc(settings.juma):'Уточните время в вашей мечети. В настройках можно сохранить его.')+'</p></section>':'';return juma+'<p class="muted" style="margin-top:22px">'+(usesAlHakk()?'<a href="https://al-hakk.ru/namaz/" target="_blank" rel="noopener">Аль-Хакк · Тюмень</a> Аср: '+(Number(settings.school)===1?'ханафитский':'первое время · '+(asrInfo(currentDay,days)?.kind==='calculated'?'расчёт Aladhan':asrInfo(currentDay,days)?.label||'недоступно')+'')+'':settings.mosque?'Время вашей мечети · введено вручную':esc(methods[settings.method])+' · Аср: '+(Number(settings.school)===1?'ханафитский':'по трём другим имамам'))+'<a class="text-button" href="#settings">Настроить</a></p>'+(error?'<div class="error">'+esc(error)+' <button class="text-button" id="retry">Повторить</button></div>':'')}
function prayerPage(){app.innerHTML=title('Мой день',settings.city?.name||'')+'<div class="central-day">'+dayPanel()+'<a class="text-button" href="#history">История отметок</a></div>';bindMarks()}
function bindMarks(){app.querySelectorAll('[data-day-mark]').forEach(b=>b.onclick=()=>{const key=b.dataset.dayMark;const saved=markPrayer(currentDay,key,history[currentDay]?.[key]?null:'done');render();if(!saved)toast('Не удалось сохранить. Проверьте доступ к хранилищу.');if(saved&&settings.haptic)navigator.vibrate?.(12)});app.querySelectorAll('[data-adhkar-open]').forEach(a=>a.onclick=()=>selectAdhkar(a.dataset.adhkarOpen));app.querySelectorAll('[data-time-toggle]').forEach(b=>b.addEventListener('click',()=>{prayerDisplay=prayerDisplay==='focus'?'timetable':'focus';render();app.querySelector('.central-prayer')?.focus({preventScroll:true})}));app.querySelector('#weather-status')?.addEventListener('click',weatherDialog);app.querySelectorAll('[data-mark]').forEach(b=>b.onclick=()=>markDialog(b.dataset.mark));app.querySelector('#retry')?.addEventListener('click',()=>refresh(true))}
function markDialog(key){const name=prayers.find(p=>p[0]===key)?.[1];modal('<div class="modal-head"><h2>'+name+'</h2><button class="icon-button" data-close aria-label="Закрыть">×</button></div><p class="muted">Личная отметка за сегодня.</p><div class="button-row"><button class="button" data-value="ontime">Совершил вовремя</button><button class="button secondary" data-value="later">Совершил позже</button><button class="text-button" data-value="">Убрать отметку</button></div>');document.querySelectorAll('[data-value]').forEach(b=>b.onclick=()=>{const saved=markPrayer(currentDay,key,b.dataset.value||null);closeModal();render();toast(saved?'Отметка сохранена':'Не удалось сохранить. Проверьте доступ к хранилищу.');if(settings.haptic)navigator.vibrate?.(12)})}
function pending(name,description){app.innerHTML=title(name)+'<section class="panel section"><span class="eyebrow">СЛЕДУЮЩИЙ ЭТАП SALAH</span><h2 style="margin-top:20px">'+description+'</h2><p class="muted">Этот раздел ещё не включён в первый релиз. Он появится после проверки религиозных текстов, источников и аудио.</p><p class="muted">Сейчас доступны время намаза, личные отметки, календарь, живая атмосфера и Кибла.</p><a class="button" href="#home">На главную</a></section>'}
function more(){app.innerHTML=title('Ещё','Всё необходимое в спокойном пространстве.')+'<section class="panel section">'+[['qibla','Кибла','Направление молитвы'],['day','Мой день','Отметки совершённых намазов'],['calendar','Календарь','Расписание'],['history','Мои молитвы','Личные отметки'],['sources','Источники','Откуда поступают данные'],['settings','Настройки','Город, расчёт и атмосфера'],['about','О SALAH','Приватность и установка']].map(([r,n,s])=>'<a class="list-button" href="#'+r+'"><span>'+(r==='settings'?'<img class="settings-menu-icon" src="./assets/gear.svg" alt="">':'')+n+'</span><small>'+s+'</small></a>').join('')+'</section>'}
function render(){topHeader.append(locationControl,settingsControl);currentRoute=(location.hash.slice(1)||'home').split('?')[0];document.body.classList.toggle('home-page',currentRoute==='home');document.body.classList.toggle('qibla-page-open',currentRoute==='qibla');if(currentRoute!=='qibla')stopCompass();if(currentRoute!=='learning')stopLearning();if(currentRoute!=='quran')stopQuran();if(currentRoute!=='adhkar')stopAdhkar();nav();if(currentRoute==='home')home();else if(currentRoute==='prayer'||currentRoute==='day')prayerPage();else if(currentRoute==='knowledge')showKnowledge(app,{onStart:kind=>{learningEntry=kind;location.hash='learning'}});else if(currentRoute==='more')more();else if(currentRoute==='quran'){if(quranRenderedHash!==location.hash||!app.querySelector('.quran-reader,.quran-library')){quranRenderedHash=location.hash;showQuran(app)}}else if(currentRoute==='adhkar')showAdhkar(app);else if(currentRoute==='learning'){const entry=learningEntry;learningEntry=null;showLearning(app,entry);}else if(currentRoute==='qibla')qibla();else if(currentRoute==='settings')settingsPage();else if(currentRoute==='history')historyPage();else if(currentRoute==='calendar')calendarPage();else if(currentRoute==='sources')sourcesPage();else if(currentRoute==='about')about();else {location.hash='home';return}document.getElementById('connection').hidden=navigator.onLine;if(!storageAvailable)app.insertAdjacentHTML('afterbegin','<p class="storage-warning">Хранилище недоступно. Изменения не сохраняются после закрытия.</p>');else if(storageWarnings.length)app.insertAdjacentHTML('afterbegin','<p class="storage-warning">Часть сохранённых записей повреждена и не загружена. Проверьте личные данные и резервную копию.</p>');tick()}
async function refresh(force=false){const id=++refreshId;error='';if(!settings.city){days={};render();return}loading=true;days=cachedDays();currentDay=dateKey();render();try{let fetched=await loadMonth(currentDay,force);if(id!==refreshId)return;days=fetched;const tomorrow=addDays(currentDay,1);if(!days[tomorrow]){const nextMonth=await loadMonth(tomorrow);if(id!==refreshId)return;days=nextMonth}if(id!==refreshId)return;const timezone=days[currentDay]?.timezone;if(timezone&&timezone!==settings.city.timezone){updateSettings({city:{...settings.city,timezone}});currentDay=dateKey();if(!days[currentDay]){const shifted=await loadMonth(currentDay);if(id!==refreshId)return;days=shifted}}await ensureTahajjudDays();if(id!==refreshId)return }catch{if(id!==refreshId)return;error=days[currentDay]?'Используется сохранённое расписание. Новые данные временно недоступны.':'Не удалось получить расписание. Проверьте интернет или внесите данные после подключения.'}finally{if(id===refreshId){loading=false;render()}}if(settings.weather&&!weatherBusy)refreshWeather()}
let lastTick=Date.now(),lastWeatherCheck=0,weatherRequestId=0,weatherBusy=false;
async function refreshWeather(){
 const id=++weatherRequestId,city=settings.city?{...settings.city}:null,key=weatherKey(city);
 lastWeatherCheck=Date.now();
 if(!settings.weather||!key){weather=null;weatherBusy=false;tick();return}
 weather=cachedWeather(city);weatherBusy=true;tick();
 try{const value=await loadWeather(city);if(id===weatherRequestId&&settings.weather&&weatherKey(settings.city)===key)weather=value}
 catch{if(id===weatherRequestId&&weatherKey(settings.city)===key)weather=cachedWeather(city)}
 finally{if(id===weatherRequestId){weatherBusy=false;tick()}}
}
function tick(){const now=Date.now(),day=dateKey();reminders.tick(now);if(day!==currentDay){currentDay=day;refresh();return}if(Math.abs(now-lastTick)>65000&&!loading){lastTick=now;refresh();return}lastTick=now;const next=nextPrayer(now,currentDay,days);const visibleNext=currentRoute==='home'?homeEvent(now,next,timingsFor(currentDay,days)?.Sunrise,currentDay):next;const el=document.getElementById('countdown');if(el&&visibleNext){el.textContent=countdown(visibleNext.time-now);document.getElementById('next-name').textContent=visibleNext.name;document.getElementById('next-time').textContent=formatTime(visibleNext.time);document.getElementById('next-note').textContent='';const prefix=document.getElementById('next-prefix');if(prefix)prefix.textContent=visibleNext.key==='Sunrise'?'':'Следующий ';const source=document.getElementById('next-source');if(source)source.hidden=!(visibleNext.key==='Asr'&&asrInfo(visibleNext.day,days)?.kind==='calculated');app.querySelectorAll('[data-prayer]').forEach(row=>row.classList.toggle('next',row.dataset.prayer===visibleNext.key&&visibleNext.day===currentDay))}const nightRow=app.querySelector('[data-prayer="Tahajjud"]');if(nightRow){const night=tahajjudEntry(now);nightRow.querySelector('time').textContent=night?.text||'—';nightRow.title=night?.label||'Нет сохранённых данных для расчёта'}const w=document.getElementById('weather-status');if(w){w.hidden=!settings.weather;w.textContent=weatherLabel();}atmosphere(now,days[currentDay]?{Fajr:Date.parse(days[currentDay].timings.Fajr),Sunrise:Date.parse(days[currentDay].timings.Sunrise),Maghrib:Date.parse(days[currentDay].timings.Maghrib)}:null,weather);if(settings.weather&&now-lastWeatherCheck>1800000&&!weatherBusy)refreshWeather()}
function onboarding(){modal('<span class="eyebrow">ДОБРО ПОЖАЛОВАТЬ</span><div class="modal-head"><h2 style="margin-top:18px">SALAH</h2><button class="icon-button" data-close aria-label="Закрыть">×</button></div><h3>Намаз. Каждый день.</h3><p class="muted">Выберите город и метод расчёта. Регистрация не нужна. Личные отметки хранятся на вашем устройстве.</p><button class="button" id="begin">Указать город</button>');document.getElementById('begin').onclick=cityDialog}
function cityDialog(){modal('<div class="modal-head"><h2>Ваш город</h2><button class="icon-button" data-close aria-label="Закрыть">×</button></div><p class="muted">SALAH использует местоположение для времени намаза и направления Киблы. При включённой живой погоде координаты передаются также сервису погоды.</p><button class="button secondary" id="geolocate">Определить местоположение</button><form id="city-search"><div class="field"><label for="city-name">Город</label><input id="city-name" placeholder="Например, Тюмень" required minlength="2" autocomplete="address-level2"></div><button class="button">Найти город</button></form><div id="city-results" aria-live="polite"></div>');document.getElementById('city-search').onsubmit=async e=>{e.preventDefault();const query=document.getElementById('city-name').value.trim();const results=document.getElementById('city-results');results.innerHTML='<p class="muted">Ищем город…</p>';try{const response=await fetch('https://geocoding-api.open-meteo.com/v1/search?name='+encodeURIComponent(query)+'&count=10&language=ru&format=json',{signal:AbortSignal.timeout(15000)});if(!response.ok)throw Error();const j=await response.json();results.innerHTML=(j.results||[]).map((c,i)=>'<button class="list-button" data-city="'+i+'"><span>'+esc(c.name)+'</span><small>'+esc(c.country+' · '+(c.admin1||''))+'</small></button>').join('')||'<p class="muted">Город не найден. Попробуйте другое написание.</p>';results.querySelectorAll('[data-city]').forEach(b=>b.onclick=()=>selectCity(j.results[Number(b.dataset.city)]))}catch{results.innerHTML='<p class="muted">Поиск временно недоступен. Попробуйте ещё раз при подключении к интернету.</p>'}};document.getElementById('geolocate').onclick=()=>{if(!navigator.geolocation){toast('Геолокация недоступна. Выберите город вручную.');return}const b=document.getElementById('geolocate');b.disabled=true;b.textContent='Определяем…';navigator.geolocation.getCurrentPosition(pos=>selectCity({name:'Моё местоположение',latitude:pos.coords.latitude,longitude:pos.coords.longitude,timezone:Intl.DateTimeFormat().resolvedOptions().timeZone}),()=>{b.disabled=false;b.textContent='Определить местоположение';toast('Местоположение не получено. Выберите город вручную.')},{enableHighAccuracy:false,timeout:15000,maximumAge:300000})}}
function selectCity(city){reminders.reset();calendarRequestId++;updateSettings({city:{name:city.name,country:city.country||'',latitude:city.latitude,longitude:city.longitude,timezone:city.timezone},onboarded:true});closeModal();days={};weatherRequestId++;weatherBusy=false;weather=null;lastWeatherCheck=0;refresh();if(!settings.onboarded)onboarding();location.hash='settings';toast('Город сохранён. Проверьте метод расчёта.')}
document.addEventListener('click',event=>{const link=event.target.closest?.('a[href]');if(link?.getAttribute('href')==='#qibla')prepareQiblaAccess();},true);
window.addEventListener('hashchange',()=>{if(currentRoute==='qibla')stopCompass();render();window.scrollTo({top:0,behavior:'instant'})});window.addEventListener('online',()=>refresh());window.addEventListener('offline',()=>render());document.addEventListener('visibilitychange',()=>{if(!document.hidden)refresh()});document.getElementById('location-button').onclick=cityDialog;document.getElementById('settings-button').onclick=()=>location.hash='settings';setInterval(tick,1000);refresh();if(!settings.onboarded)setTimeout(onboarding,500);registerAppWorker({toast});

function settingsPage(){app.innerHTML=title('Настройки','Настройте SALAH под свой город и привычный порядок.')+'<form id="settings-form"><div class="settings-grid"><section class="panel"><h2>Время намаза</h2><p class="muted">Для Тюмени используется опубликованная таблица <a href="https://al-hakk.ru/namaz/" target="_blank" rel="noopener">Аль-Хакк</a>: сентябрь–октябрь 2026. Расчётные методы, поправки и ручной режим к опубликованным временам этой таблицы не применяются. Первое время Асра рассчитывается отдельно.</p><button type="button" class="button secondary" id="change-city">'+esc(settings.city?.name||'Выбрать город')+'</button><div class="field"><label for="method">Метод расчёта</label><select id="method">'+Object.entries(methods).map(([id,n])=>'<option value="'+id+'" '+(Number(settings.method)===Number(id)?'selected':'')+'>'+n+'</option>').join('')+'</select></div><p class="muted">Уточните подходящий метод по расписанию местной мечети.</p><div class="field"><label for="school">Расчёт Асра</label><select id="school"><option value="0" '+(Number(settings.school)===0?'selected':'')+'>По трём другим имамам (шафиитский, маликитский, ханбалитский)</option><option value="1" '+(Number(settings.school)===1?'selected':'')+'>Ханафитский</option></select><p class="muted">'+(usesAlHakk()?'Для Тюмени ханафитский Аср взят из Аль-Хакк. Первое время для шафиитского, маликитского и ханбалитского мазхабов рассчитано Aladhan по координатам города и отмечено как «расчёт». Оно сохраняется для работы без интернета.':'Ханафитский расчёт: тень вдвое длиннее предмета. По трём другим имамам: тень равна длине предмета. В обоих случаях учитывается тень в солнечный полдень.')+'</p></div><div class="field"><label for="high-latitude">Высокие широты</label><select id="high-latitude">'+[[3,'По углу сумерек'],[1,'Середина ночи'],[2,'Одна седьмая ночи']].map(([v,n])=>'<option value="'+v+'" '+(Number(settings.highLatitude)===v?'selected':'')+'>'+n+'</option>').join('')+'</select></div><h3 style="margin-top:25px">Корректировки, минут</h3><div class="adjustments">'+prayers.map(([k,n])=>'<div class="field"><label for="offset-'+k+'">'+n+'</label><input id="offset-'+k+'" type="number" min="-60" max="60" step="1" value="'+Number(settings.offsets[k])+'"></div>').join('')+'</div><p class="muted">Положительное значение переносит время вперёд.</p><div class="field"><label for="hijri-offset">Поправка исламского календаря</label><select id="hijri-offset">'+[[-1,'−1 день'],[0,'Без поправки'],[1,'+1 день']].map(([value,label])=>'<option value="'+value+'" '+(Number(settings.hijriOffset||0)===value?'selected':'')+'>'+label+'</option>').join('')+'</select><p class="muted">Применяется только к исламской дате в календаре.</p></div><h3 style="margin-top:25px">Тахаджуд</h3><label class="switch-row" for="show-tahajjud"><span>Показывать в расписании</span><input id="show-tahajjud" type="checkbox" '+(settings.showTahajjud?'checked':'')+'></label><div class="field"><label for="tahajjud-time">Личное время (необязательно)</label><input id="tahajjud-time" type="time" value="'+esc(settings.tahajjudTime)+'" '+(settings.showTahajjud?'':'disabled')+'><p class="muted">Оставьте поле пустым для расчёта.</p></div><p class="muted">По умолчанию — начало последней трети ночи от Магриба до следующего Фаджра. Это ориентир для ночной молитвы, а не обязательное фиксированное время. <a href="https://sunnah.com/bukhari:1145" target="_blank" rel="noopener">Аль-Бухари, 1145</a></p></section><section class="panel"><h2>Живая атмосфера</h2><div class="field"><span class="background-mode-label" id="background-mode-label">Фон главной</span><div class="background-mode-buttons" id="background-mode" role="group" aria-labelledby="background-mode-label">'+[['light','День','sun'],['dark','Ночь','moon-stars'],['auto','Переход','clock']].map(([value,label,icon])=>'<button type="button" data-background-mode="'+value+'" aria-pressed="'+(settings.backgroundMode===value)+'"><img src="./assets/'+icon+'.svg" alt="" aria-hidden="true"><span>'+label+'</span></button>').join('')+'</div></div>'+[['transitions','Плавные переходы'],['weather','Живая погода'],['weatherAnimation','Анимация погоды'],['motion','Уменьшить движение'],['haptic','Тактильный отклик']].map(([k,n])=>'<label class="switch-row" for="'+k+'"><span>'+n+'</span><input id="'+k+'" type="checkbox" '+(settings[k]?'checked':'')+'></label>').join('')+'<button type="button" class="weather-settings-status" id="weather-status" '+(settings.weather?'':'hidden')+'>'+weatherLabel()+'</button><p class="muted">Системная настройка уменьшения движения учитывается автоматически. Погода обновляется не чаще раза в 30 минут.</p><button type="button" class="button secondary" id="scene-preview">Посмотреть смену дня и ночи</button><button type="button" class="button secondary" id="weather-preview" style="margin-top:10px">Посмотреть погоду</button><p class="muted" id="background-mode-note" style="margin-top:14px" '+(settings.backgroundMode==='auto'?'':'hidden')+'>Фон постепенно светлеет от Фаджра к восходу и темнеет на закате.</p><div id="reminder-settings"></div><h3 style="margin-top:25px">Данные и приватность</h3><p class="muted">Резервная копия включает настройки, историю намазов, закладки Корана, место чтения, прогресс уроков и счётчики азкаров. Тексты и аудио скачиваются отдельно.</p><button type="button" class="button secondary" id="export">Экспортировать данные</button><button type="button" class="button secondary" id="import" style="margin-top:10px">Восстановить из копии</button><input id="backup-file" type="file" accept="application/json,.json" hidden></section><section class="panel"><h2>Расписание мечети</h2><label class="switch-row"><span>Следовать расписанию мечети</span><input id="mosque" type="checkbox" '+(settings.mosque?'checked':'')+'></label><p class="muted">Введите пять времён для сегодняшнего дня. Времена действуют ежедневно, пока вы их не измените или не отключите режим. Проверьте актуальность перед использованием.</p><div class="adjustments">'+prayers.map(([k,n])=>'<div class="field"><label for="mosque-'+k+'">'+n+'</label><input id="mosque-'+k+'" type="time" value="'+esc(settings.mosqueTimes[k]||'')+'"></div>').join('')+'</div><div class="field"><label for="juma">Время Джума вашей мечети (необязательно)</label><input id="juma" type="time" value="'+esc(settings.juma)+'"></div><p class="muted">Джума не заменяет автоматически время Зухра.</p></section><section class="panel"><h2>Установка SALAH</h2><p class="muted">На iPhone: откройте в Safari → «Поделиться» → «На экран Домой». На Android: меню браузера → «Установить приложение».</p><p class="muted">Откройте ссылку SALAH в Safari. После добавления на экран «Домой» запускайте приложение с его значка. Новая версия появится по тому же адресу; личные настройки сохранятся.</p><button type="button" class="button secondary" id="install">Установить приложение</button><button type="button" class="button secondary" id="check-update" style="margin-top:10px">Проверить обновления</button><p class="muted" style="margin-top:18px">Портретный режим включён для поддерживающих его установленных приложений. На iPhone включите блокировку книжной ориентации в Пункте управления.</p><p class="muted" style="margin-top:18px">Тестовая версия 0.5</p></section></div><div class="button-row"><button class="button">Сохранить настройки</button></div></form>';reminders.mountSettings(document.getElementById('reminder-settings'));document.getElementById('change-city').onclick=cityDialog;document.getElementById('show-tahajjud').onchange=async e=>{const saved=updateSettings({showTahajjud:e.target.checked});document.getElementById('tahajjud-time').disabled=!settings.showTahajjud;if(!saved)toast('Не удалось сохранить настройку Тахаджуда');await ensureTahajjudDays();if(currentRoute==='home')render();else tick()};document.getElementById('tahajjud-time').onchange=e=>{if(!e.target.validity.valid)return;const saved=updateSettings({tahajjudTime:personalTime(e.target.value)});if(!saved)toast('Не удалось сохранить личное время')};app.querySelectorAll('[data-background-mode]').forEach(button=>button.onclick=()=>{const saved=updateSettings({backgroundMode:button.dataset.backgroundMode});app.querySelectorAll('[data-background-mode]').forEach(choice=>choice.setAttribute('aria-pressed',String(choice.dataset.backgroundMode===settings.backgroundMode)));document.getElementById('background-mode-note').hidden=settings.backgroundMode!=='auto';tick();if(!saved)toast('Не удалось сохранить выбор фона')});document.getElementById('scene-preview').onclick=()=>{startScenePreview();location.hash='home'};document.getElementById('weather-preview').onclick=()=>{startWeatherPreview();location.hash='home'};document.getElementById('weather-status').onclick=weatherDialog;for(const flag of ['weather','weatherAnimation'])document.getElementById(flag).onchange=e=>{const saved=updateSettings({[flag]:e.target.checked});if(flag==='weather'){if(settings.weather)refreshWeather();else{weatherRequestId++;weatherBusy=false;weather=null;lastWeatherCheck=0;tick()}}else tick();if(!saved)toast('Не удалось сохранить настройку погоды')};document.getElementById('install').onclick=installApp;document.getElementById('check-update').onclick=async e=>{const button=e.currentTarget;button.disabled=true;try{const result=await checkAppUpdate();toast({available:'Новая версия готова. Нажмите «Обновить».',loading:'Обновление загружается. Кнопка появится, когда оно будет готово.',current:'У вас последняя версия приложения.',offline:'Для проверки обновлений подключитесь к интернету.',unavailable:'Обновления пока недоступны. Откройте SALAH по HTTPS-ссылке ещё раз.'}[result]);}catch{toast('Не удалось проверить обновление. Попробуйте позже.')}finally{if(button.isConnected)button.disabled=false}};document.getElementById('export').onclick=exportData;document.getElementById('import').onclick=()=>document.getElementById('backup-file').click();document.getElementById('backup-file').onchange=importData;document.getElementById('settings-form').onsubmit=e=>{e.preventDefault();let offsets={},mosqueTimes={};for(const[k]of prayers){offsets[k]=Number(document.getElementById('offset-'+k).value);mosqueTimes[k]=document.getElementById('mosque-'+k).value}const mosque=document.getElementById('mosque').checked;if(mosque&&prayers.some(([k])=>!mosqueTimes[k])){toast('Введите все пять времён расписания мечети.');return}let flags={};for(const k of['transitions','weather','weatherAnimation','motion','haptic'])flags[k]=document.getElementById(k).checked;reminders.reset();calendarRequestId++;const saved=updateSettings({...flags,hijriOffset:Number(document.getElementById('hijri-offset').value),backgroundMode:settings.backgroundMode,method:Number(document.getElementById('method').value),school:Number(document.getElementById('school').value),highLatitude:Number(document.getElementById('high-latitude').value),offsets,mosque,mosqueTimes,juma:document.getElementById('juma').value,showTahajjud:document.getElementById('show-tahajjud').checked,tahajjudTime:personalTime(document.getElementById('tahajjud-time').value)});toast(saved?'Настройки сохранены':'Не удалось сохранить настройки');refresh()}}
let historyPeriod='month';
function historyPage(){
 const start=historyPeriod==='week'?addDays(currentDay,-6):historyPeriod==='month'?currentDay.slice(0,7)+'-01':null;
 const rows=Object.keys(history).sort().reverse().filter(d=>(!start||d>=start)&&d<=currentDay&&prayers.some(([k])=>history[d][k]));
 app.innerHTML=title('Мои молитвы','Приватная история ваших отметок.')+'<section class="panel section"><div class="button-row" style="margin:0 0 22px">'+[['week','Неделя'],['month','Месяц'],['all','Всё время']].map(([value,label])=>'<button type="button" class="button '+(historyPeriod===value?'':'secondary')+'" data-history-period="'+value+'" aria-pressed="'+(historyPeriod===value)+'">'+label+'</button>').join('')+'</div><div class="panel-head"><h2>Личный ритм</h2><span class="muted">'+rows.length+' дней с отметками</span></div>'+(!rows.length?'<p class="muted">Пока нет отметок. Отметьте совершённую молитву в разделе «Мой день».</p>':rows.map(d=>'<div class="history-row"><span>'+new Intl.DateTimeFormat('ru-RU',{day:'numeric',month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(d+'T12:00:00Z'))+'</span><div class="history-marks">'+prayers.map(([k,n])=>'<span title="'+n+': '+(history[d][k]?'совершён':'нет отметки')+'" aria-label="'+n+': '+(history[d][k]?'отмечено':'нет отметки')+'">'+(history[d][k]?'✓':'○')+'</span>').join('')+'</div></div>').join(''))+'<p class="muted" style="margin:23px 0 0">Ваши отметки помогают видеть свой ритм. Они не оценивают поклонение.</p></section>';
 app.querySelectorAll('[data-history-period]').forEach(button=>button.onclick=()=>{historyPeriod=button.dataset.historyPeriod;historyPage()});
}

let calendarMode='week',calendarStart=null,calendarRequestId=0;
async function calendarPage(){
 const request=++calendarRequestId;
 if(!settings.city){app.innerHTML=title('Календарь')+'<section class="panel"><p class="muted">Выберите город, чтобы получить расписание.</p><button id="calendar-city" class="button">Выбрать город</button></section>';document.getElementById('calendar-city').onclick=cityDialog;return}
 calendarStart=calendarStart||currentDay;
 const valid=/^\d{4}-\d{2}-\d{2}$/.test(calendarStart)&&Number.isFinite(Date.parse(calendarStart+'T12:00:00Z'));
 if(!valid){calendarStart=currentDay}
 const count=calendarMode==='day'?1:calendarMode==='week'?7:new Date(Date.UTC(Number(calendarStart.slice(0,4)),Number(calendarStart.slice(5,7)),0)).getUTCDate();
 const start=calendarMode==='month'?calendarStart.slice(0,7)+'-01':calendarStart,end=addDays(start,count-1),cityKey=JSON.stringify([settings.city,settings.method,settings.school,settings.highLatitude]);
 const stillCurrent=()=>request===calendarRequestId&&currentRoute==='calendar'&&cityKey===JSON.stringify([settings.city,settings.method,settings.school,settings.highLatitude]);
 const hijri=hijriForDay(start,days,settings.hijriOffset),friday=Array.from({length:count},(_,i)=>addDays(start,i)).find(d=>new Date(d+'T12:00:00Z').getUTCDay()===5);
 app.innerHTML=title('Календарь',(usesAlHakk()?'Расписание Аль-Хакк':'Время по выбранному методу')+' · '+settings.city.name)+'<section class="panel"><div class="button-row" style="margin:0 0 22px">'+[['day','Сегодня'],['week','Неделя'],['month','Месяц']].map(([v,n])=>'<button class="button '+(calendarMode===v?'':'secondary')+'" data-period="'+v+'" aria-pressed="'+(calendarMode===v)+'">'+n+'</button>').join('')+'</div><div class="field"><label for="calendar-date">Начальная дата</label><input id="calendar-date" type="date" min="1900-01-01" max="2200-12-31" value="'+start+'"></div>'+(hijri?'<p class="calendar-hijri"><strong>'+esc(hijri.text)+'</strong><span class="muted">'+esc(hijri.source)+(Number(settings.hijriOffset)&&!hijri.adjustmentUnavailable?' · поправка '+(settings.hijriOffset>0?'+':'')+settings.hijriOffset:'')+'</span></p>':'')+'<div class="table-scroll"><table class="calendar-table"><thead><tr><th>Дата</th>'+['Фаджр','Восход¹','Зухр','Аср','Магриб','Иша'].map(n=>'<th>'+n+'</th>').join('')+'</tr></thead><tbody>'+Array.from({length:count},(_,i)=>{const d=addDays(start,i),t=timingsFor(d,days);return'<tr><td>'+d.slice(8)+'.'+d.slice(5,7)+'</td>'+['Fajr','Sunrise','Dhuhr','Asr','Maghrib','Isha'].map(k=>'<td>'+(t?formatTime(t[k]):'—')+'</td>').join('')+'</tr>'}).join('')+'</tbody></table></div><p class="muted" style="margin-top:20px">¹ Восход не является намазом.'+(settings.mosque?' Включён ручной режим: ежедневные времена мечети одинаковы.':'')+'</p>'+(friday?'<div class="calendar-friday"><h3>Джума · '+friday.slice(8)+'.'+friday.slice(5,7)+'</h3><p class="muted">'+(settings.juma?'Время вашей мечети: '+esc(settings.juma):'Уточните время в своей мечети. Его можно сохранить в настройках.')+'</p></div>':'')+'<div id="calendar-status" class="muted" role="status"></div></section>';
 app.querySelectorAll('[data-period]').forEach(b=>b.onclick=()=>{calendarMode=b.dataset.period;if(calendarMode==='day')calendarStart=currentDay;calendarPage()});
 document.getElementById('calendar-date').onchange=e=>{if(e.target.validity.valid&&e.target.value){calendarStart=e.target.value;calendarPage()}};
 if(!days[start]||!days[end]){try{document.getElementById('calendar-status').textContent='Загружаем расписание…';const first=await loadMonth(start);if(!stillCurrent())return;const last=start.slice(0,7)===end.slice(0,7)?first:await loadMonth(end);if(!stillCurrent())return;days={...days,...first,...last};calendarPage()}catch{if(stillCurrent())document.getElementById('calendar-status').textContent=usesAlHakk()?'На выбранные даты расписание Аль-Хакк пока не подключено. Сохранённые дни отображаются.':'Расписание недоступно. Сохранённые дни отображаются.'}}
}

function qibla(){const city=settings.city,key=JSON.stringify([city?.name,city?.latitude,city?.longitude]);if(qiblaHandle?.key===key&&app.querySelector('.qibla-page'))return;stopCompass();qiblaHandle={...mountQibla(app,{city,onChooseCity:cityDialog,haptics:()=>settings.haptic}),key}}
function stopCompass(){qiblaHandle?.destroy();qiblaHandle=null}

function sourcesPage(){app.innerHTML=title('Источники','Проверяемые данные и прозрачные ограничения.')+'<div class="stack section"><section class="panel"><h2>Времена молитв</h2><p class="muted">Для Тюмени опубликованные времена, включая ханафитский Аср: <a href="https://al-hakk.ru/namaz/" target="_blank" rel="noopener">Аль-Хакк</a> (сентябрь–октябрь 2026). Первое время Асра: отдельный расчёт Aladhan для трёх других имамов, координаты 57.1522° N, 65.5272° E, часовой пояс Asia/Yekaterinburg, метод MWL. Уточнение первого времени на 30 сентября 2026: 15:25, предоставлено пользователем.</p><p class="muted">Для других городов — AlAdhan Prayer Times API. Выбранный метод: '+esc(methods[settings.method])+'. Расчёт зависит от координат, метода, Асра и правила высоких широт. Уточняйте соответствие расписанию местной мечети.</p><a class="text-button" href="https://aladhan.com/prayer-times-api" target="_blank" rel="noopener">Документация AlAdhan</a><a class="text-button" href="https://aladhan.com/calculation-methods" target="_blank" rel="noopener">Методы расчёта</a><p class="muted" style="margin-top:16px">Исламская дата берётся из AlAdhan, когда она присутствует в расписании; иначе используется расчётный календарь islamic-civil. Источник отмечен в календаре. Доступна поправка −1/0/+1 день; наблюдение луны может отличаться.</p></section><section class="panel"><h2>Погода и города</h2><p class="muted">Open-Meteo · погодные данные и поиск городов. Данные погоды старше двух часов не используются для анимации.</p><a class="text-button" href="https://open-meteo.com/" target="_blank" rel="noopener">Open-Meteo · CC BY 4.0</a></section><section class="panel"><h2>Кибла</h2><p class="muted">Начальный азимут большого круга от выбранных координат к Каабе: 21.422487° N, 39.826206° E. Направление относительно телефона доступно только при подтверждённых показаниях датчика. Магнитное направление iPhone и абсолютные показания Android приводятся к географическому северу по автономной модели WMM2025 NOAA/BGS; срок модели — 2025–2029.</p><a class="text-button" href="https://www.ncei.noaa.gov/products/world-magnetic-model" target="_blank" rel="noopener">Магнитная модель NOAA/BGS</a><a class="text-button" href="./assets/geomagnetism-LICENSE.txt" target="_blank" rel="noopener">Лицензия geomagnetism · Apache-2.0</a></section><section class="panel"><h2>Религиозные материалы</h2><a class="text-button" href="#learning">Открыть обучение и источники каждого шага</a><p class="muted">Обучение намазу и омовению содержит ссылки на хадисы аль-Бухари и Муслима, руководства Umma.ru, Islam.uz и пояснения правовых школ. Коранические тексты: Al Quran Cloud · Uthmani, перевод Эльмира Кулиева. Аудио: аль-Афаси, аль-Хусари, аль-Миншави, Ясир ад-Даусари, Махер аль-Муайкли и Бадр ат-Турки. У Бадра ат-Турки запись целой суры. Кириллическая транскрипция: Islam.Global, для Аль-Фатихи — пробная собственная запись SALAH, которая требует проверки специалистом. Текстовые пояснения сверены с источниками; полноценная богословская редактура ещё не проведена.</p><p class="muted">Записи формул в обучении и азкарах: <a href="https://www.hisnmuslim.com/" target="_blank" rel="noopener">HisnMuslim</a>, при совпадении с текстом карточки.</p></section><section class="panel"><h2>Азан</h2><p class="muted">Записи Мансура аз-Захрани и Мишари аль-Афаси из <a href="https://aladhan.com/play" target="_blank" rel="noopener">каталога AlAdhan / Islamic Network</a>. Отдельная запись Фаджра — Мансур аз-Захрани. <a href="https://community.islamic.network/d/232-request-to-use-your-adhan-audio-in-a-non-commercial-islamic-app" target="_blank" rel="noopener">Разрешение на использование в бесплатном приложении</a>.</p></section></div>'}
function about(){app.innerHTML=title('О SALAH','Тестовая версия 0.5')+'<div class="stack section"><section class="panel"><h2>Намаз. Каждый день.</h2><p class="muted">SALAH создан как спокойный ежедневный помощник мусульманина. Поклонение — не игра. Здесь нет рейтингов, баллов и сравнений пользователей.</p><h3>Конфиденциальность</h3><p class="muted">Настройки и история молитв сохраняются локально. При расчёте времени координаты передаются AlAdhan, при поиске города и включённой погоде — Open-Meteo. В приложении нет рекламных и аналитических трекеров.</p><p class="muted">Очистка данных браузера удалит историю. Для переноса сохраните резервную копию в настройках и восстановите её на другом устройстве. Перед восстановлением показывается состав копии.</p><h3>Без интернета</h3><p class="muted">После первой успешной загрузки доступен интерфейс и сохранённое расписание. Несохранённые даты, поиск города и свежая погода требуют интернета.</p></section><section class="panel"><h2>Что уже доступно</h2><p class="muted">Расписание пяти намазов, отсчёт до следующего, отметки совершённых молитв, календарь, ручные поправки, расписание мечети, живая атмосфера, погода, Кибла, пошаговое обучение, азкары с накопительным счётчиком и Коран: 114 сур, перевод Кулиева, кириллическая транскрипция, аудио, закладки и сохранение для чтения без интернета.</p><h3>Следующие этапы</h3><p class="muted">Азан и напоминания доступны при открытом приложении. Доставка при закрытом приложении и синхронизация между устройствами ещё не подключены. Также остаются проверка на физических телефонах и богословская редактура материалов.</p><a class="button secondary" href="#sources">Источники</a></section></div>'}
function exportData(){let backup;try{backup=createBackup({storage:localStorage,settings,history})}catch{toast('Не удалось прочитать данные для резервной копии');return}const blob=new Blob([JSON.stringify(backup,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='salah-backup-'+currentDay+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(backup.warnings?.length?'Копия подготовлена. Некоторые повреждённые записи пропущены.':'Резервная копия подготовлена')}
let installPrompt=null;window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e});async function installApp(){if(installPrompt){await installPrompt.prompt();installPrompt=null}else toast('В меню браузера выберите «Установить» или «На экран Домой».')}
if(document.modelContext?.registerTool){const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});const register=tool=>{try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{})}catch{}};register({name:'read_prayer_schedule',description:'Прочитать доступное расписание и следующую молитву для выбранного города.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({city:settings.city?.name||null,date:currentDay,next:nextPrayer(Date.now(),currentDay,days),times:timingsFor(currentDay,days),method:methods[settings.method]})});register({name:'set_prayer_mark',description:'Сохранить личную отметку сегодняшней молитвы или убрать её.',inputSchema:{type:'object',properties:{prayer:{type:'string',enum:prayers.map(p=>p[0])},status:{type:'string',enum:['ontime','later','clear']}},required:['prayer','status'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||!prayers.some(p=>p[0]===input.prayer)||!['ontime','later','clear'].includes(input.status))throw Error('Недопустимая молитва или статус');if(!markPrayer(currentDay,input.prayer,input.status==='clear'?null:input.status))throw Error('Хранилище недоступно');render();return{date:currentDay,prayer:input.prayer,status:history[currentDay][input.prayer]}}})}

function weatherDialog(){if(!settings.weather){location.hash='settings';return}const fresh=weatherFrame(weather,Date.now()).fresh;modal('<div class="modal-head"><h2>Погода</h2><button class="icon-button" data-close aria-label="Закрыть">×</button></div><h3>'+esc(settings.city?.name||'')+'</h3>'+(fresh?'<p class="muted">'+weatherName(weather.weather_code)+'<br>Температура: '+Math.round(weather.temperature_2m)+'°<br>Ощущается как: '+Math.round(weather.apparent_temperature)+'°'+(Number.isFinite(weather.wind_speed_10m)?'<br>Ветер: '+Math.round(weather.wind_speed_10m)+' м/с':'')+'<br>Данные на: '+new Intl.DateTimeFormat('ru-RU',{timeZone:settings.city?.timezone,dateStyle:'short',timeStyle:'short'}).format(new Date(weather.dataAt))+'</p>':'<p class="muted">Свежая погода пока недоступна. '+(weather?'Сохранённые данные устарели. ':'')+'Фон показывает время суток.</p>')+'<a class="text-button" href="https://open-meteo.com/" target="_blank" rel="noopener">Источник: Open-Meteo</a>')}

async function importData(event){
 const input=event.target,file=input.files?.[0];input.value='';if(!file)return;
 if(file.size>5*1024*1024){toast('Файл слишком большой для резервной копии SALAH');return}
 let prepared;try{prepared=validateBackup(await file.text())}catch(error){toast(error.message||'Не удалось прочитать резервную копию');return}
 const p=prepared.preview;
 modal('<div class="modal-head"><h2>Восстановить данные?</h2><button class="icon-button" data-close aria-label="Закрыть">×</button></div><p class="muted">Настройки и история будут заменены данными из этой копии. Сначала можно сохранить текущие данные.</p><div class="backup-preview"><p>Город: '+esc(p.city||'Не выбран')+'</p><p>Дней в истории: '+p.days+' · Отметок: '+p.prayerMarks+'</p><p>Закладок Корана: '+p.bookmarks+'</p><p>Повторений азкаров: '+p.adhkarRepetitions.toLocaleString('ru-RU')+'</p></div>'+(prepared.warnings.length?'<p class="muted">'+prepared.warnings.map(esc).join('<br>')+'</p>':'')+'<div class="button-row"><button type="button" class="button secondary" id="backup-current">Сохранить текущую копию</button><button type="button" class="button" id="restore-backup">Восстановить</button></div>');
 document.getElementById('backup-current').onclick=exportData;
 document.getElementById('restore-backup').onclick=()=>{try{restoreBackup(prepared,{storage:localStorage,confirmed:true});closeModal();reminders.reset();stopCompass();stopLearning();stopAdhkar();stopQuran();quranRenderedHash=null;calendarRequestId++;days={};weatherRequestId++;weatherBusy=false;weather=null;lastWeatherCheck=0;currentDay=dateKey();location.hash='settings';refresh();toast('Данные восстановлены')}catch(error){toast(error.message||'Не удалось восстановить данные')}};
}
